            List<Map<String,Object>> found=new ArrayList<Map<String,Object>>(maps(group.get("files")));for(Map<String,Object>d:maps(group.get("documents")))found.addAll(maps(d.get("files")));for(Map<String,Object>f:found)files.computeIfAbsent(key(baseName(first(f.get("originalName"),f.get("name"))).replaceFirst("^\\d+_","")),k->new ArrayList<Map<String,Object>>()).add(f);
