    public Map<String,Object> file(Object value,String entityPath){if(!present(value))return null;List<Map<String,Object>>found=files.getOrDefault(key(baseName(value)),Collections.emptyList());if(found.size()!=1)throw new IllegalArgumentException("Для файла «"+baseName(value)+"» найдено соответствий: "+found.size());Map<String,Object>f=copy(found.get(0));f.put("_id",first(f.get("_id"),f.get("id"),f.get("fileId")));f.put("originalName",first(f.get("originalName"),f.get("name")));f.put("isFile",true);f.put("allowExternal",bool(f.get("allowExternal")));f.put("entityFieldPath",entityPath);return f;}
